"use client";

import { useState } from "react";
import { teamMembers } from "@/data/home";
import { PhotoSlot } from "@/components/ui/PhotoSlot";
import { SectionHeading } from "@/components/ui/SectionHeading";
export function PeopleShowcase() {
  const [activeIndex, setActiveIndex] = useState(0);
  const activeMember = teamMembers[activeIndex];
  return <section id="people" className="people section-dark"><SectionHeading number="03" title="THE PEOPLE" description="The minds and hearts behind the movement." /><div className="people-stage"><div className="people-copy"><p className="section-number">{String(activeIndex + 1).padStart(2, "0")}</p><h3>{activeMember.name}</h3><p className="eyebrow">{activeMember.role}</p><p>Building communities, creating opportunities.</p><span className="asset-note">Profile bio and social links to be verified.</span></div><PhotoSlot className="portrait-slot" label={`${activeMember.name} portrait`} src={activeMember.image} /></div><ol className="member-strip">{teamMembers.map((member, index) => <li key={member.name}><button type="button" className={index === activeIndex ? "is-active" : ""} onClick={() => setActiveIndex(index)} aria-pressed={index === activeIndex}><span>{String(index + 1).padStart(2, "0")}</span><strong>{member.name}</strong><small>{member.role}</small></button></li>)}</ol></section>;
}
